                  <td className="px-6 py-4">
                     <span className="inline-flex items-center gap-1 text-xs font-medium text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded">
                        {candidate.plan === 'pro' ? <Zap size={12} className="text-purple-500" /> : <User size={12} />}
                        {candidate.plan === 'pro' ? 'Base Ativa' : 'Candidatura'}
                     </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium capitalize ${
                      candidate.status === 'completed' ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300' :
                      candidate.status === 'processing' ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300' :
                      'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300'
                    }`}>
                      {candidate.status === 'completed' ? 'Pronto' : 'Processando'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
